//! Naive pluralization matching the C++ library: just append "s".

/// `pluralize("")` yields `""`; anything else gets "s" appended,
/// regardless of how the word ends.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    if word.is_empty() {
        return Vec::new();
    }
    let mut out = word.to_vec();
    out.push(b's');
    out
}

/// A word counts as plural when its last byte is a lowercase 's'.
pub fn is_plural(word: &[u8]) -> bool {
    word.last() == Some(&b's')
}

