//! Case transformations. All of them are byte-oriented with C-locale
//! semantics: only ASCII letters change case, everything else passes
//! through untouched.

/// Split on '_', uppercase the first byte of each segment, drop the
/// underscores. When `lower_first` is set, the first byte of the input
/// is emitted unchanged (empty leading segments still force an
/// uppercase on the first real byte, matching the C++ state machine).
pub fn camelize(word: &[u8], lower_first: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut upper_next = !lower_first;
    for &b in word {
        if b == b'_' {
            upper_next = true;
            continue;
        }
        if upper_next {
            out.push(b.to_ascii_uppercase());
            upper_next = false;
        } else {
            out.push(b);
        }
    }
    out
}

/// Words are delimited by the space byte only; the first byte of each
/// word is uppercased and every other byte lowercased.
pub fn titleize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    let mut word_start = true;
    for &b in word {
        if b == b' ' {
            out.push(b);
            word_start = true;
        } else if word_start {
            out.push(b.to_ascii_uppercase());
            word_start = false;
        } else {
            out.push(b.to_ascii_lowercase());
        }
    }
    out
}

/// Uppercase the first byte, lowercase all remaining bytes.
pub fn capitalize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for (i, &b) in word.iter().enumerate() {
        if i == 0 {
            out.push(b.to_ascii_uppercase());
        } else {
            out.push(b.to_ascii_lowercase());
        }
    }
    out
}

