//! Port of tests/test11.cpp from the inflection-cpp project.
//!
//! Usage: test11 <number> <word>
//! Prints the results of 11 Inflector API calls, one per line.

mod inflection;

use inflection::Inflector;
use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn push_line(out: &mut Vec<u8>, line: &[u8]) {
    out.extend_from_slice(line);
    out.push(b'\n'); // std::endl
}

fn main() {
    Inflector::initialize();

    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    if args.len() > 2 {
        let num = inflection::number::atoi(args[1].as_bytes());
        let word = args[2].as_bytes();

        // Build the whole output as raw bytes: truncate() may cut a
        // multi-byte UTF-8 sequence, which a String cannot represent.
        let mut out = Vec::new();
        push_line(&mut out, &Inflector::pluralize(word));
        push_line(&mut out, &Inflector::ordinalize(num));
        push_line(&mut out, &Inflector::camelize(word, true));
        push_line(&mut out, &Inflector::camelize(word, false));
        push_line(&mut out, &Inflector::titleize(word));
        push_line(&mut out, &Inflector::capitalize(word));
        push_line(&mut out, &Inflector::truncate(word, 5, b"..."));
        push_line(&mut out, &Inflector::truncate(word, 10, b"~"));
        push_line(&mut out, &Inflector::parameterize(word, b"-"));
        push_line(&mut out, &Inflector::parameterize(word, b"_"));
        let plural: &[u8] = if Inflector::is_plural(word) { b"1" } else { b"0" };
        push_line(&mut out, plural);

        std::io::stdout().write_all(&out).unwrap();
    }
}

